def max_sum_of_three_subarrays(nums, k):
    n = len(nums)
    best_sum = -1
    best_indices = []
    for i in range(n - k + 1):
        for j in range(i + k, n - k + 1):
            for l in range(j + k, n - k + 1):
                total = sum(nums[i:i + k]) + sum(nums[j:j + k]) + sum(nums[l:l + k])   # sum all three windows directly, from scratch
                if total > best_sum:
                    best_sum = total
                    best_indices = [i, j, l]
    return best_indices


if __name__ == "__main__":
    print(max_sum_of_three_subarrays([1, 2, 1, 2, 6, 7, 5, 1], 2))

