import java.util.*;

public class Main {
    int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int bestSum = -1;
        int[] bestIndices = new int[3];
        for (int i = 0; i + k <= n; i++) {
            for (int j = i + k; j + k <= n; j++) {
                for (int l = j + k; l + k <= n; l++) {
                    int total = 0;
                    for (int x = i; x < i + k; x++) total += nums[x];                        // sum all three windows directly, from scratch
                    for (int x = j; x < j + k; x++) total += nums[x];
                    for (int x = l; x < l + k; x++) total += nums[x];
                    if (total > bestSum) {
                        bestSum = total;
                        bestIndices = new int[]{i, j, l};
                    }
                }
            }
        }
        return bestIndices;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.maxSumOfThreeSubarrays(new int[]{1, 2, 1, 2, 6, 7, 5, 1}, 2)));
    }
}

