import java.util.*;

public class Main {
    int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int numWindows = n - k + 1;
        int[] windowSums = new int[numWindows];                                   // windowSums[i] = sum of nums[i..i+k-1], built with a fixed-size sliding window
        int total = 0;
        for (int i = 0; i < k; i++) total += nums[i];
        windowSums[0] = total;
        for (int i = k; i < n; i++) {
            total += nums[i] - nums[i - k];
            windowSums[i - k + 1] = total;
        }

        int[] left = new int[numWindows];                                          // left[i] = index of the best (earliest-on-tie) window in [0, i]
        int bestLeft = 0;
        for (int i = 0; i < numWindows; i++) {
            if (windowSums[i] > windowSums[bestLeft]) bestLeft = i;
            left[i] = bestLeft;
        }

        int[] right = new int[numWindows];                                        // right[i] = index of the best (earliest-on-tie) window in [i, end]
        int bestRight = numWindows - 1;
        for (int i = numWindows - 1; i >= 0; i--) {
            if (windowSums[i] >= windowSums[bestRight]) bestRight = i;             // >= keeps the EARLIEST index among ties, for lexicographically smallest results
            right[i] = bestRight;
        }

        int bestSum = -1;
        int[] result = new int[3];
        for (int j = k; j <= numWindows - 1 - k; j++) {                            // try every possible position for the MIDDLE window
            int l = left[j - k], r = right[j + k];
            int sum3 = windowSums[l] + windowSums[j] + windowSums[r];
            if (sum3 > bestSum) {
                bestSum = sum3;
                result = new int[]{l, j, r};
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.maxSumOfThreeSubarrays(new int[]{1, 2, 1, 2, 6, 7, 5, 1}, 2)));
    }
}

